/* IST is a fixed +5:30 with no daylight saving, so the whole thing is
   arithmetic: shift the epoch and read the UTC fields. Intl formatting is
   fine once a second but this runs every animation frame. */
const IST_SHIFT = 330 * 60000;

const istNow = () => {
  const d = new Date(Date.now() + IST_SHIFT);
  return {
    h24: d.getUTCHours(),
    m: d.getUTCMinutes(),
    s: d.getUTCSeconds(),
    ms: d.getUTCMilliseconds(),
  };
};

const istParts = () => {
  const { h24, m } = istNow();
  /* getTimezoneOffset is minutes to ADD to local to reach UTC, so a visitor's
     own offset is its negation. IST is +330. */
  const diffMin = 330 + new Date().getTimezoneOffset();
  const ah = Math.floor(Math.abs(diffMin) / 60);
  const am = Math.abs(diffMin) % 60;
  const delta =
    diffMin === 0
      ? "same clock as you"
      : `${ah}h${am ? ` ${am}m` : ""} ${
          diffMin > 0 ? "ahead of" : "behind"
        } you`;

  return { awake: h24 >= 8, angle: (h24 + m / 60) * 15, delta };
};

/* His clock — a real analog face, and the digits beside it.

   One requestAnimationFrame loop drives both: it writes the hand rotations
   and the text straight to the DOM through refs. Sixty React renders a second
   to move a second hand would be absurd, and the whole point of the readout
   is that it is visibly running. */
export function TimeDial() {
  const [day, setDay] = useState(istParts);

  const hmRef = useRef(null);
  const secRef = useRef(null);
  const csRef = useRef(null);
  const apRef = useRef(null);
  const hourRef = useRef(null);
  const minRef = useRef(null);
  const secHandRef = useRef(null);

  // the awake/asleep band and the delta only need refreshing now and then
  useEffect(() => {
    const id = setInterval(() => setDay(istParts()), 30000);
    return () => clearInterval(id);
  }, []);

  useEffect(() => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)")
      .matches;
    let raf = null;
    let timer = null;
    let lastHm = "";
    let lastSec = "";

    const pad = (n) => String(n).padStart(2, "0");
    const spin = (ref, deg) => {
      if (ref.current) ref.current.style.transform = `rotate(${deg}deg)`;
    };

    const write = (smooth) => {
      const { h24, m, s, ms } = istNow();

      /* Hands. The minute and hour hands carry the fraction of the unit below
         them, or they jump in steps and the face reads as broken. */
      const sub = smooth ? ms / 1000 : 0;
      spin(secHandRef, (s + sub) * 6);
      spin(minRef, (m + s / 60) * 6);
      spin(hourRef, ((h24 % 12) + m / 60) * 30);

      const hm = `${h24 % 12 || 12}:${pad(m)}`;
      if (hm !== lastHm) {
        lastHm = hm;
        if (hmRef.current) hmRef.current.textContent = hm;
        if (apRef.current) apRef.current.textContent = h24 < 12 ? "am" : "pm";
      }
      const sec = pad(s);
      if (sec !== lastSec) {
        lastSec = sec;
        if (secRef.current) secRef.current.textContent = sec;
      }
      if (smooth && csRef.current) {
        csRef.current.textContent = pad(Math.floor(ms / 10));
      }
    };

    if (reduce) {
      write(false);
      timer = setInterval(() => write(false), 1000);
      return () => clearInterval(timer);
    }

    const loop = () => {
      write(true);
      raf = requestAnimationFrame(loop);
    };
    const start = () => {
      if (!raf) raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      if (raf) {
        cancelAnimationFrame(raf);
        raf = null;
      }
    };

    /* The loop only runs while the clock is on screen. A sweeping second hand
       is worth a frame's work when someone can watch it and nothing at all
       once they have scrolled past the hero. */
    const host = hmRef.current?.closest(".ct-dial-row");
    let obs = null;
    if (host && typeof IntersectionObserver !== "undefined") {
      obs = new IntersectionObserver(
        ([entry]) => (entry.isIntersecting ? start() : stop()),
        { threshold: 0 }
      );
      obs.observe(host);
    } else {
      start();
    }

    return () => {
      stop();
      if (obs) obs.disconnect();
    };
  }, []);

  return (
    <span className={`ct-dial-row${day.awake ? " is-awake" : ""}`}>
      <svg className="ct-dial" viewBox="0 0 52 52" aria-hidden="true">
        {/* the outer band is the whole 24-hour day: the hours he is usually
            reachable are lit, the small hours are not */}
        {Array.from({ length: 24 }, (_, h) => (
          <line
            key={h}
            className={`ct-dial-tick${h >= 8 ? " is-awake" : ""}`}
            x1="26"
            y1="2.5"
            x2="26"
            y2={h % 6 === 0 ? "6.5" : "5"}
            transform={`rotate(${h * 15} 26 26)`}
          />
        ))}

        {/* the face the hands live on */}
        <circle className="ct-dial-face" cx="26" cy="26" r="18" />
        {Array.from({ length: 12 }, (_, h) => (
          <line
            key={`f${h}`}
            className={`ct-dial-hour-mark${h % 3 === 0 ? " is-quarter" : ""}`}
            x1="26"
            y1="10"
            x2="26"
            y2={h % 3 === 0 ? "13.5" : "12"}
            transform={`rotate(${h * 30} 26 26)`}
          />
        ))}

        <g className="ct-dial-hands">
          <line
            className="ct-hand ct-hand-hour"
            ref={hourRef}
            x1="26"
            y1="26"
            x2="26"
            y2="17"
          />
          <line
            className="ct-hand ct-hand-min"
            ref={minRef}
            x1="26"
            y1="26"
            x2="26"
            y2="13"
          />
          <line
            className="ct-hand ct-hand-sec"
            ref={secHandRef}
            x1="26"
            y1="28.5"
            x2="26"
            y2="11"
          />
        </g>
        <circle className="ct-dial-hub" cx="26" cy="26" r="1.6" />
      </svg>

      <span className="ct-dial-text">
        <b className="ct-clock">
          <span className="ct-clock-hm" ref={hmRef}>
            --:--
          </span>
          <span className="ct-clock-tail">
            <span className="ct-clock-sec" ref={secRef}>
              --
            </span>
            <em className="ct-clock-cs" ref={csRef} aria-hidden="true">
              --
            </em>
            <i className="ct-clock-ap" ref={apRef}>
              --
            </i>
          </span>
        </b>
        <span>
          {day.awake ? "likely awake" : "asleep"} · {day.delta}
        </span>
      </span>
    </span>
  );
}

/* Openers the composer cycles through. Real first lines, not "Say hello" —
   the point is to show the visitor the kind of message that gets answered. */
const OPENERS = [
  "We're hiring for a GenAI role…",
  "Can you look at our RAG pipeline?",
  "Quick question about your IIT Delhi work…",
  "I'd like to talk about a collaboration…",
];

/* Types an opener out, holds it, deletes it, moves to the next. It stops the
   moment the visitor types anything of their own — a placeholder that keeps
   animating under real text is just noise. */
export function useTypedPlaceholder(active) {
  const [text, setText] = useState("");
  useEffect(() => {
    if (!active) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setText(OPENERS[0]);
      return undefined;
    }
    let i = 0;
    let n = 0;
    let deleting = false;
    let timer;
    const tick = () => {
      const full = OPENERS[i];
      n += deleting ? -1 : 1;
      setText(full.slice(0, n));
      let wait = deleting ? 26 : 52;
      if (!deleting && n === full.length) {
        deleting = true;
        wait = 2100;
      } else if (deleting && n === 0) {
        deleting = false;
        i = (i + 1) % OPENERS.length;
        wait = 320;
      }
      timer = setTimeout(tick, wait);
    };
    timer = setTimeout(tick, 700);
    return () => clearTimeout(timer);
  }, [active]);
  return text;
}

/* The hero's own one-line composer. The page exists to get a message written,
   so the first screen lets you start writing instead of asking you to travel
   to a form and start there. What you type is carried down into the real
   message field. */
export function HeroComposer({ onSend }) {
  const [text, setText] = useState("");
  const ghost = useTypedPlaceholder(text.length === 0);

  const send = () => {
    const v = text.trim();
    if (!v) return;
    onSend(v);
    setText("");
  };

  return (
    <div className={`ct-composer${text ? " is-typing" : ""}`}>
      <label className="ct-composer-field">
        <span className="sr-only">Start your message</span>
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              send();
            }
          }}
          /* The real placeholder attribute cannot animate, so the cycling
             opener is a sibling the input sits on top of. */
          placeholder=""
          aria-label="Start your message"
        />
        {!text && (
          <span className="ct-composer-ghost" aria-hidden="true">
            {ghost}
            <i />
          </span>
        )}
      </label>
      <button
        type="button"
        className="ct-composer-go"
        onClick={send}
        disabled={!text.trim()}
        aria-label="Continue to the message form"
      >
        <span aria-hidden="true">→</span>
      </button>
    </div>
  );
}

/* The accent word, letter by letter. Each letter clips its own slice of one
   gradient — background-size is the whole word, background-position this
   letter's share of it — so the colour still runs continuously across the
   word even though every letter is transformed on its own. A single
   background on the parent cannot survive that: background-clip: text breaks
   as soon as a child gets its own layer. */
export function LivingWord({ text, className = "" }) {
  const ref = useRef(null);
  /* A wave runs through the letters once, shortly after load, so the word
     shows what it does before anyone thinks to point at it. The class is
     removed again when the wave finishes: an animation left in place would
     keep overriding the cursor's own writes to --heat, since animations beat
     inline styles in the cascade. */
  const [intro, setIntro] = useState(false);

  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    // late enough to land as the hero's reveal settles, not under it
    const on = setTimeout(() => setIntro(true), 560);
    const off = setTimeout(
      () => setIntro(false),
      560 + 1100 + text.length * 55
    );
    return () => {
      clearTimeout(on);
      clearTimeout(off);
    };
  }, [text]);

  useEffect(() => {
    const wrap = ref.current;
    if (!wrap) return undefined;
    if (!window.matchMedia("(pointer: fine)").matches) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;

    const letters = Array.from(wrap.querySelectorAll(".ct-l"));
    if (!letters.length) return undefined;

    const REACH = 170;
    let raf = null;
    let px = 0;
    let py = 0;
    const last = [];

    /* Geometry is read every frame rather than cached. Caching it looked like
       the cheap option and was simply wrong: the web font swaps in after
       mount and the section's reveal transform is still running, so positions
       measured once were tens of pixels out and every letter read as
       out-of-range forever. Nine rects is a single layout read, and all of
       them happen before any style is written — never interleaved, or the
       browser relayouts between each pair. */
    const paint = () => {
      raf = null;
      const wrapBox = wrap.getBoundingClientRect();
      if (wrapBox.bottom < -REACH || wrapBox.top > window.innerHeight + REACH) {
        return;
      }
      const boxes = letters.map((el) => el.getBoundingClientRect());
      for (let i = 0; i < letters.length; i++) {
        const b = boxes[i];
        const cx = b.left + b.width / 2;
        const cy = b.top + b.height / 2;
        const d = Math.hypot(px - cx, py - cy);
        // squared falloff, so the nearest letter takes nearly all the lift and
        // it reads as one letter reacting rather than the whole word heaving
        const heat = d > REACH ? 0 : (1 - d / REACH) ** 2;
        const v = heat.toFixed(3);
        if (v === last[i]) continue;
        last[i] = v;
        letters[i].style.setProperty("--heat", v);
        letters[i].style.setProperty(
          "--tilt",
          `${(((px - cx) / REACH) * heat * -6).toFixed(2)}deg`
        );
      }
    };

    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!raf) raf = requestAnimationFrame(paint);
    };
    const onLeave = () => {
      letters.forEach((el, i) => {
        last[i] = "0.000";
        el.style.setProperty("--heat", "0");
        el.style.setProperty("--tilt", "0deg");
      });
    };

    window.addEventListener("mousemove", onMove, { passive: true });
    window.addEventListener("mouseleave", onLeave);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseleave", onLeave);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [text]);

  const chars = text.split("");
  return (
    <span
      className={`ct-living ${className}${intro ? " is-intro" : ""}`}
      ref={ref}
      style={{ "--n": chars.length }}
      aria-hidden="true"
    >
      {chars.map((ch, i) => (
        <span className="ct-l" key={`${ch}-${i}`} style={{ "--i": i }}>
          {ch === " " ? "\u00a0" : ch}
        </span>
      ))}
    </span>
  );
}

export function FaqRow({ question, answer }) {
  const [open, setOpen] = useState(false);
  return (
    <div className={`ct-faq-row${open ? " is-open" : ""}`}>
      <button
        type="button"
        className="ct-faq-q"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
      >
        <span>{question}</span>
        <i className="ct-faq-sign" aria-hidden="true" />
      </button>
      <div className="ct-faq-a-wrap">
        <p className="ct-faq-a">{answer}</p>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- motion */
/* The four ambient behaviours the page runs, each a hook so a variant opts
   into exactly the ones its layout wants. All four no-op under
   prefers-reduced-motion or on a coarse pointer, and all four batch their
   writes into one rAF rather than one per event. */

/* html and body carry overflow-x: clip sitewide, which makes window.scrollTo
   and scrollIntoView no-ops. Every programmatic scroll on this page has to be
   animated by hand against documentElement.scrollTop. */
export function useSmoothScroll() {
  return React.useCallback((targetY) => {
    const root = document.documentElement;
    const start = root.scrollTop;
    const dist = targetY - start;
    if (Math.abs(dist) < 2) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      root.scrollTop = targetY;
      return;
    }
    const t0 = performance.now();
    const dur = Math.min(900, 320 + Math.abs(dist) * 0.22);
    const step = (t) => {
      const p = Math.min(1, (t - t0) / dur);
      const e = 1 - Math.pow(1 - p, 3); // easeOutCubic
      root.scrollTop = start + dist * e;
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }, []);
}

/* Reveal on scroll. react-reveal (still a dependency) mounts children hidden
   and relies on legacy lifecycles; an observer setting one class does the same
   job without shipping a second animation runtime. */
export function useReveal(rootRef, deps = []) {
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return undefined;
    const targets = Array.from(root.querySelectorAll("[data-reveal]"));
    if (typeof IntersectionObserver === "undefined") {
      targets.forEach((el) => el.classList.add("is-in"));
      return undefined;
    }
    const obs = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          entry.target.classList.add("is-in");
          obs.unobserve(entry.target);
        });
      },
      { rootMargin: "0px 0px -12% 0px", threshold: 0.08 }
    );
    targets.forEach((el) => obs.observe(el));
    return () => obs.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/* Magnetism. Every [data-magnet] control leans toward the pointer once it is
   within reach and springs back when it leaves — one window listener
   measuring all of them, rather than a listener per button. */
export function useMagnetism(rootRef) {
  useEffect(() => {
    if (window.matchMedia("(pointer: coarse)").matches) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    const root = rootRef.current;
    if (!root) return undefined;

    let pending = false;
    let px = 0;
    let py = 0;
    const REACH = 88; // px of empty space around a control that still pulls
    const PULL = 0.32; // fraction of the distance the control travels

    const paint = () => {
      pending = false;
      root.querySelectorAll("[data-magnet]").forEach((el) => {
        const r = el.getBoundingClientRect();
        if (!r.width) return;
        const dx = px - (r.left + r.width / 2);
        const dy = py - (r.top + r.height / 2);
        const reach = Math.max(r.width, r.height) / 2 + REACH;
        const dist = Math.hypot(dx, dy);
        const on = el.classList.contains("is-magnet");
        if (dist < reach) {
          const k = (1 - dist / reach) * PULL;
          el.style.setProperty("--mag-x", `${(dx * k).toFixed(1)}px`);
          el.style.setProperty("--mag-y", `${(dy * k).toFixed(1)}px`);
          if (!on) el.classList.add("is-magnet");
        } else if (on) {
          el.style.setProperty("--mag-x", "0px");
          el.style.setProperty("--mag-y", "0px");
          el.classList.remove("is-magnet");
        }
      });
    };

    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!pending) {
        pending = true;
        requestAnimationFrame(paint);
      }
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => window.removeEventListener("mousemove", onMove);
  }, [rootRef]);
}

/* Page-wide torch, picking up the tint of whatever [data-torch] element it
   happens to be over. */
export function useTorch(cursorRef, accentColor) {
  useEffect(() => {
    let pending = false;
    let px = 0;
    let py = 0;
    const paint = () => {
      pending = false;
      const c = cursorRef.current;
      if (!c) return;
      c.style.setProperty("--cx", `${px}px`);
      c.style.setProperty("--cy", `${py}px`);
      const host = document.elementFromPoint(px, py);
      const tinted = host && host.closest("[data-torch]");
      c.style.setProperty("--torch", tinted ? tinted.dataset.torch : accentColor);
      c.style.setProperty("--torch-r", tinted ? "520px" : "760px");
    };
    const onMove = (e) => {
      px = e.clientX;
      py = e.clientY;
      if (!pending) {
        pending = true;
        requestAnimationFrame(paint);
      }
      if (cursorRef.current) cursorRef.current.classList.add("is-on");
    };
    window.addEventListener("mousemove", onMove, { passive: true });
    return () => window.removeEventListener("mousemove", onMove);
  }, [cursorRef, accentColor]);
}

/* Cursor-following spotlight plus a couple of degrees of tilt, shared by the
   portrait and the channel rows. Past about 4deg the type starts to smear. */
export function useSpotlight() {
  const onSpot = React.useCallback((e) => {
    if (window.innerWidth < 769) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const el = e.currentTarget;
    const r = el.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width;
    const y = (e.clientY - r.top) / r.height;
    el.style.setProperty("--mx", `${(x * 100).toFixed(1)}%`);
    el.style.setProperty("--my", `${(y * 100).toFixed(1)}%`);
    el.style.setProperty("--ry", `${((x - 0.5) * 3).toFixed(2)}deg`);
    el.style.setProperty("--rx", `${((0.5 - y) * 2.2).toFixed(2)}deg`);
    /* Parallax: the halo trails the plate and the tag leads it, so the three
       read as objects at different depths rather than one flat picture. */
    el.style.setProperty("--px", `${(x - 0.5).toFixed(3)}`);
    el.style.setProperty("--py", `${(y - 0.5).toFixed(3)}`);
  }, []);

  const offSpot = React.useCallback((e) => {
    const el = e.currentTarget;
    el.style.setProperty("--rx", "0deg");
    el.style.setProperty("--ry", "0deg");
    el.style.setProperty("--px", "0");
    el.style.setProperty("--py", "0");
  }, []);

  return { onSpot, offSpot };
}

/* Scroll progress through an element, 0 before it enters and 1 once it has
   left, written to a CSS custom property rather than through React state.
   Scroll-linked animation at 60fps cannot go through a render. */
export function useScrollProgress(ref, prop = "--p", opts = {}) {
  const { start = 1, end = 0 } = opts;
  useEffect(() => {
    const el = ref.current;
    if (!el) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      el.style.setProperty(prop, "1");
      return undefined;
    }
    let pending = false;
    let visible = true;
    const paint = () => {
      pending = false;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight;
      /* 0 when the element's top is `start` viewports down, 1 when its bottom
         is `end` viewports up. */
      const total = r.height + vh * (start + end);
      const travelled = vh * start - r.top;
      const p = Math.min(1, Math.max(0, travelled / total));
      el.style.setProperty(prop, p.toFixed(4));
    };
    const onScroll = () => {
      if (!visible || pending) return;
      pending = true;
      requestAnimationFrame(paint);
    };
    let obs = null;
    if (typeof IntersectionObserver !== "undefined") {
      obs = new IntersectionObserver(
        ([entry]) => {
          visible = entry.isIntersecting;
          if (visible) onScroll();
        },
        { rootMargin: "50% 0px" }
      );
      obs.observe(el);
    }
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    paint();
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (obs) obs.disconnect();
    };
  }, [ref, prop, start, end]);
}

/* Cursor-driven multi-layer parallax.
 *
 * Adapted from a Tailwind/TS "wilderness" hero that stacked 18 mountain and
 * fog PNGs. The depth model is the good part and it is kept exactly:
 * every layer carries its own speedX / speedY / speedZ and a rotateY
 * factor, and is composed as
 *
 *   perspective(2300px) translate3d(x, y, z) rotateY(deg)
 *
 * with the Z term signed by which half of the viewport the layer sits in,
 * so layers lean towards the pointer rather than all sliding the same way.
 * A 450ms ease-out transition on transform (see .ct-px CSS) is left running
 * while this writes every frame — that constant restart is what gives the
 * layers their trailing drift, and here the lag is the effect.
 *
 * Two things are deliberately not ported. The original set three pieces of
 * React state on every mousemove, so it re-rendered the whole scene per
 * frame; this writes to the DOM through refs instead. And it read
 * getComputedStyle(el).left per layer per frame, interleaving layout reads
 * with style writes — every rect here is read before anything is written.
 *
 * Opt in by putting data-px="sx,sy,sz,rot" on any element that has no
 * transform of its own.
 */
export function useParallax(rootRef, deps = []) {
  useEffect(() => {
    if (!window.matchMedia("(pointer: fine)").matches) return undefined;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches)
      return undefined;
    const root = rootRef.current;
    if (!root) return undefined;

    const layers = Array.from(root.querySelectorAll("[data-px]")).map((el) => {
      const [sx, sy, sz, rot] = (el.dataset.px || "")
        .split(",")
        .map((n) => parseFloat(n) || 0);
      return { el, sx, sy, sz, rot };
    });
    if (!layers.length) return undefined;

    let raf = null;
    let cx = 0;
    let cy = 0;
    let inView = true;

    const paint = () => {
      raf = null;
      const halfW = window.innerWidth / 2;
      const halfH = window.innerHeight / 2;
      const xVal = cx - halfW;
      const yVal = cy - halfH;
      const rotateDeg = (xVal / halfW) * 20;

      // every read first, then every write — never interleaved
      const boxes = layers.map((l) => l.el.getBoundingClientRect());

      for (let i = 0; i < layers.length; i++) {
        const l = layers[i];
        const b = boxes[i];
        const centreX = b.left + b.width / 2;
        const isInLeft = centreX < halfW ? 1 : -1;
        const zValue = (cx - centreX) * isInLeft * 0.1;

        l.el.style.transform =
          `perspective(2300px) translate3d(` +
          `${(-xVal * l.sx).toFixed(2)}px,` +
          `${(yVal * l.sy).toFixed(2)}px,` +
          `${(zValue * l.sz).toFixed(2)}px) ` +
          `rotateY(${(rotateDeg * l.rot).toFixed(3)}deg)`;
      }
    };

    const onMove = (e) => {
      cx = e.clientX;
      cy = e.clientY;
      if (inView && !raf) raf = requestAnimationFrame(paint);
    };

    /* The hero is one screen of a long page; there is no reason to keep
       measuring it once it has been scrolled past. */
    let obs = null;
    if (typeof IntersectionObserver !== "undefined") {
      obs = new IntersectionObserver(
        ([entry]) => {
          inView = entry.isIntersecting;
        },
        { threshold: 0 }
      );
      obs.observe(root);
    }

    window.addEventListener("mousemove", onMove, { passive: true });
    return () => {
      window.removeEventListener("mousemove", onMove);
      if (obs) obs.disconnect();
      if (raf) cancelAnimationFrame(raf);
      layers.forEach((l) => {
        l.el.style.transform = "";
      });
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}
