/* The one place a contact message is validated and sent.
 *
 * Extracted from contactform.js when the inbox layout needed the same send
 * path: two copies of the EmailJS credentials and of the template's
 * placeholder mapping is exactly the pair that drifts apart and then
 * silently delivers blank mail.
 */
import emailjs from "emailjs-com";

const SERVICE_ID = "service_xe6alve";
const TEMPLATE_ID = "template_k2u1z0k";
const PUBLIC_KEY = "ANZYSfODJvj2-066t";

/* This template was authored for the JARVIS voice assistant (see
   components/chatbot/EmailAgent.js, which sends the same one) and its
   placeholders are named for that flow, not for a web form. sendForm() posts
   inputs under their own `name` attributes — name / email / subject /
   message — so only `message` ever matched a placeholder and every other
   line in the delivered mail arrived blank.

   These are the names the template actually reads. Until there is a template
   of its own, the payload maps onto them explicitly, which is also why this
   uses send() rather than sendForm(). */
export const templateParams = (v) => ({
  from_name: v.name,
  reply_to: v.email,
  // the template renders its subject as "… - {{inquiry_type}}"
  inquiry_type: v.subject,
  message: v.message,
  // the JARVIS flow collects these; a web form does not, and EmailJS renders
  // a missing placeholder as an empty line rather than omitting it
  phone: "Not provided",
  company: "Not provided",
  project: "Not provided",
  timestamp: new Date().toLocaleString("en-IN", { timeZone: "Asia/Kolkata" }),
});

export const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export const EMPTY = { name: "", email: "", subject: "", message: "" };

/* Both layouts carry `noValidate` so the browser's own error bubbles don't
   clash with the page styling — which means every `required` is inert and
   validation has to happen here instead. */
export const validate = (values) => {
  const errors = {};
  if (!values.name) errors.name = "Please tell me your name.";
  else if (values.name.length < 2) errors.name = "That looks too short.";

  if (!values.email) errors.email = "I need an email to reply to.";
  else if (!EMAIL_RE.test(values.email))
    errors.email = "That doesn't look like a valid email.";

  if (!values.subject) errors.subject = "Add a subject so I know what's up.";
  else if (values.subject.length < 3) errors.subject = "That looks too short.";

  if (!values.message) errors.message = "Don't forget the message itself.";
  else if (values.message.length < 10)
    errors.message = "A little more detail would help — 10 characters minimum.";

  return errors;
};

export function sendContactMessage(values) {
  return emailjs.send(
    SERVICE_ID,
    TEMPLATE_ID,
    templateParams(values),
    PUBLIC_KEY
  );
}
