import React, { useCallback, useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import toast from "react-hot-toast";
import { FaGithub, FaEnvelope, FaFileAlt } from "react-icons/fa";

import Header from "../../components/header/Header";
import TestimonialCards from "../../components/TestimonialCards/TestimonialCards";
import ContactForm from "./contactform";
import CinematicFooter from "./CinematicFooter";

import { socialMediaLinks } from "../../portfolio.js";
import { resumeDownloadUrl } from "../../utils/downloadResume";
import portrait from "../../assets/fluent-emoji/profile_pic.jpeg";

/* The page's content and its motion machinery both live in the kit now, so
   this layout and the three in ./variants run the same engine rather than
   three copies of it. */
import {
  CHANNELS,
  ContactData,
  FaqRow,
  HeroComposer,
  LOOKING_FOR,
  LivingWord,
  TimeDial,
  inlineFaqs,
  useMagnetism,
  useParallax,
  useReveal,
  useSmoothScroll,
  useSpotlight,
  useTorch,
} from "./contactShared";


import "./ContactComponent.css";

const greetingResume = resumeDownloadUrl();


function Contact(props) {
  const theme = props.theme;
  const formRef = useRef(null);
  const cursorRef = useRef(null);
  const rootRef = useRef(null);
  const heroRef = useRef(null);
  const [copied, setCopied] = useState(false);
  /* Gates the hero's entrance. One frame after mount, so the transitions
     have a "from" state to run out of rather than starting mid-flight. */
  const [ready, setReady] = useState(false);

  useEffect(() => {
    /* rAF gives the browser one paint with the "from" state, so the
       transitions have something to run out of instead of starting
       mid-flight. It never fires in a background tab, though, so a timer
       backs it up — otherwise opening this page in a new tab leaves the
       hero blank until the tab is focused. */
    const raf = requestAnimationFrame(() => setReady(true));
    const timer = setTimeout(() => setReady(true), 400);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(timer);
    };
  }, []);
  /* What the hero composer captured, handed to the form below. The key is
     what makes a repeat send land — the same text twice is still a new
     instruction to refill and refocus. */
  const [seed, setSeed] = useState(null);

  const scrollToY = useSmoothScroll();

  const scrollToForm = useCallback(() => {
    const el = formRef.current;
    if (!el) return;
    const root = document.documentElement;
    scrollToY(el.getBoundingClientRect().top + root.scrollTop - 96);
  }, [scrollToY]);

  const toTop = useCallback(() => scrollToY(0), [scrollToY]);

  const sendDraft = useCallback(
    (text) => {
      setSeed({ text, key: Date.now() });
      scrollToForm();
    },
    [scrollToForm]
  );

  const copyEmail = useCallback(() => {
    const address = socialMediaLinks.gmail;
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(address).then(
        () => {
          setCopied(true);
          toast.success(`Copied ${address}`);
          setTimeout(() => setCopied(false), 1800);
        },
        () => toast(address)
      );
    } else {
      toast(address);
    }
  }, []);

  const { onSpot, offSpot } = useSpotlight();

  useReveal(rootRef);

  useMagnetism(rootRef);
  /* Cursor parallax across the hero's depth layers. Scoped to heroRef so
     it only ever measures the one screen it applies to. */
  useParallax(heroRef);

  /* Keyboard shortcuts. The whole page exists to get one message written, so
     the two things worth a single keystroke are writing it and taking the
     address away with you. */
  useEffect(() => {
    const onKey = (e) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const t = e.target;
      if (
        t &&
        (t.tagName === "INPUT" ||
          t.tagName === "TEXTAREA" ||
          t.isContentEditable)
      )
        return;
      const k = e.key.toLowerCase();
      if (k === "m") {
        e.preventDefault();
        scrollToForm();
        // after the scroll settles, or the browser yanks it back mid-flight
        setTimeout(() => {
          const first = document.querySelector('.contact-form [name="name"]');
          if (first) first.focus({ preventScroll: true });
        }, 820);
      } else if (k === "c") {
        e.preventDefault();
        copyEmail();
      } else if (k === "t") {
        e.preventDefault();
        toTop();
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [scrollToForm, copyEmail, toTop]);

  useTorch(cursorRef, theme.accentColor);

  return (
    /* The tokens and the [data-reveal]/[data-magnet] root both live on the
       wrapper rather than on .ct, because the curtain footer has to sit
       outside .ct's 1220px container to bleed full width — and it still
       needs the theme variables and the page's own reveal and magnetism. */
    <div
      className="contact-main"
      data-theme={theme?.name}
      ref={rootRef}
      style={{
        "--fg": theme.text,
        "--muted": theme.secondaryText,
        "--accent": theme.accentColor,
        "--accent2": theme.accentBright,
        "--bg": theme.body,
      }}
    >
      <Header theme={theme} setTheme={props.setTheme} />

      <div className={`ct is-${theme?.name === "light" ? "light" : "dark"}`}>
        <div className="ct-cursor" ref={cursorRef} aria-hidden="true" />

        {/* ============================================== hero */}
        <section
          className={`ct-hero${ready ? " is-ready" : ""}`}
          ref={heroRef}
        >
          {/* The depth stack. The original hero built this from 18 hotlinked
              mountain and fog PNGs; these are drawn in CSS instead, so
              there is nothing to hotlink and nothing to load. Each layer
              carries its own speedX,speedY,speedZ,rotateY. */}
          <div className="ct-px" aria-hidden="true">
            <span className="ct-px-grid" data-px="0.012,0.010,0,0" />
            <span className="ct-px-glow-a" data-px="0.045,0.055,0.10,0.05" />
            <span className="ct-px-glow-b" data-px="0.080,0.090,0.18,0.09" />
            <span className="ct-px-dust" data-px="0.100,0.070,0.22,0.11" />
          </div>
          <div className="ct-hero-text" data-reveal data-px="0.016,0.012,0.05,0.025">
            <p className="ct-eyebrow">
              <i />
              Get in touch
            </p>

            <h1
              className="ct-title"
              aria-label="Tell me what you're building. I'll tell you if I can help."
            >
              {/* Three masked lines rather than <br>-separated text, so each
                  one can slide up from behind its own edge on load. --l
                  staggers them. The aria-label above carries the sentence,
                  so the split is invisible to a screen reader. */}
              <span aria-hidden="true">
                <span className="ct-title-line" style={{ "--l": 0 }}>
                  <span>Tell me what</span>
                </span>
                <span className="ct-title-line" style={{ "--l": 1 }}>
                  <span>
                    you&apos;re <LivingWord text="building." className="hl" />
                  </span>
                </span>
                <span className="ct-title-line dim" style={{ "--l": 2 }}>
                  <span>I&apos;ll tell you if I can help.</span>
                </span>
              </span>
            </h1>

            <p className="ct-lede">{ContactData["description"]}</p>

            <div className="ct-facts">
              <p>
                <b>&lt; 24h</b>
                <span>typical reply</span>
              </p>
              <p className="ct-fact-clock">
                <TimeDial />
              </p>
              <p>
                <b>Chennai</b>
                <span>IST · remote-friendly</span>
              </p>
            </div>

            {/* start writing here, not two screens down */}
            <HeroComposer onSend={sendDraft} />

            {/* The composer above is the primary action now, so this row is
                just the other way of reaching him — no second button saying
                the same thing as the field. */}
            <div className="ct-actions">
              <button
                type="button"
                className={`ct-cta${copied ? " is-copied" : ""}`}
                onClick={copyEmail}
                data-magnet
              >
                <FaEnvelope aria-hidden="true" />
                {copied ? "Address copied ✓" : socialMediaLinks.gmail}
              </button>
            </div>

            <p className="ct-keys">
              <kbd>M</kbd> jumps to the full form · <kbd>C</kbd> copies the
              address
            </p>
          </div>

          {/* The right-hand column: the portrait, then the action buttons in
              the space under it. On a laptop that space was empty while the
              buttons sat below the fold in the copy column. */}
          <div className="ct-hero-side" data-reveal>
            {/* the portrait, mounted rather than floating: a plate with its
                own warm halo, an availability tag pinned to the corner, and
                the caption that used to be scattered across three chip
                strips */}
            <figure
              className="ct-portrait"
              data-px="0.042,0.032,0.34,0.15"
              data-torch="#B4593A"
              onMouseMove={onSpot}
              onMouseLeave={offSpot}
            >
              <span className="ct-portrait-halo" aria-hidden="true" />
              <span className="ct-portrait-plate">
                <span className="ct-rim" aria-hidden="true" />
                <span className="ct-spot" aria-hidden="true" />
                <img src={portrait} alt="K Laxman" />
                {/* inside the plate — parked below it, it landed on top of the
                  caption's second line */}
                <span className="ct-status">
                  <i className="ct-status-dot" aria-hidden="true" />
                  Open to opportunities
                </span>
              </span>
              <figcaption>
                <b>K Laxman</b>
                <span>
                  Senior AI Engineer, CAMS · M.Tech &amp; B.Tech, IIT Delhi
                </span>
              </figcaption>
            </figure>

            {/* The original gradient action buttons, kept as they were. */}
            <div className="button-container">
              <a
                className="general-btn"
                href={resumeDownloadUrl()}
                target="_blank"
                rel="noopener noreferrer"
                aria-label="See my Résumé"
                title="See my Résumé"
              >
                <FaFileAlt aria-hidden="true" /> Résumé
              </a>
              <Link
                className="github-btn"
                to="/github"
                aria-label="GitHub Contributions"
                title="GitHub Contributions"
              >
                <FaGithub className="github-icon" />
                GitHub
              </Link>
              <Link className="button-contact" to="/projects">
                Recent Work
              </Link>
            </div>
          </div>
        </section>

        {/* ============================================ channels */}
        <section className="ct-block" data-reveal>
          <p className="ct-section">Direct lines</p>
          <div className="ct-rail">
            {CHANNELS.map((c) => (
              <a
                key={c.name}
                className="ct-line"
                href={c.href}
                target={c.href.startsWith("mailto:") ? "_self" : "_blank"}
                rel="noopener noreferrer"
                style={{ "--ca": c.accent }}
                data-torch={c.accent}
                onMouseMove={onSpot}
                onMouseLeave={offSpot}
                onClick={c.copy ? copyEmail : undefined}
              >
                <span className="ct-rim" aria-hidden="true" />
                <span className="ct-spot" aria-hidden="true" />
                <span className="ct-line-mark" aria-hidden="true">
                  {c.icon}
                </span>
                <span className="ct-line-text">
                  <b>{c.name}</b>
                  <em>{c.handle}</em>
                </span>
                <span className="ct-line-note">{c.note}</span>
                <span className="ct-line-go" aria-hidden="true">
                  ↗
                </span>
              </a>
            ))}
          </div>
        </section>

        {/* ============================================== brief */}
        {/* A spread, not a paragraph: the ask on the left, the four things it
            actually means on the right. The right half of this section used
            to be empty while the four focus areas sat as bare text under the
            headline. */}
        <section className="ct-block ct-brief" data-reveal>
          <div className="ct-brief-grid">
            <div className="ct-brief-lead">
              <p className="ct-section">What I&apos;m looking for</p>
              <h2 className="ct-brief-title">
                Roles where I ship production AI, and grow toward{" "}
                <span className="hl">technical leadership.</span>
              </h2>
              <p className="ct-brief-note">
                Based in Chennai, from Hyderabad, and actively looking at{" "}
                <strong>Hyderabad</strong> and <strong>Bangalore</strong>.
                Remote and hybrid both work.
              </p>
              <a className="ct-brief-cta" href={greetingResume} download>
                <span>Full history in the résumé</span>
                <em aria-hidden="true">↗</em>
              </a>
            </div>

            <ol className="ct-focus">
              {LOOKING_FOR.map((f, i) => (
                <li
                  className="ct-focus-row"
                  key={f.title}
                  style={{ "--ca": f.accent }}
                  data-torch={f.accent}
                  onMouseMove={onSpot}
                  onMouseLeave={offSpot}
                >
                  <span className="ct-rim" aria-hidden="true" />
                  <span className="ct-spot" aria-hidden="true" />
                  <span className="ct-focus-no" aria-hidden="true">
                    {String(i + 1).padStart(2, "0")}
                  </span>
                  <span className="ct-focus-body">
                    <b>{f.title}</b>
                    <span>{f.note}</span>
                  </span>
                </li>
              ))}
            </ol>
          </div>
        </section>

        {/* =============================================== form */}
        <section className="ct-block ct-form-block" ref={formRef} data-reveal>
          <p className="ct-section">Send it here</p>
          <ContactForm theme={theme} seed={seed} />
        </section>

        {/* ======================================= testimonials */}
        <section className="ct-block ct-testimonials" data-reveal>
          <TestimonialCards theme={theme} />
        </section>

        {/* ================================================ faq */}
        {inlineFaqs.length > 0 && (
          <section className="ct-block ct-faq" data-reveal>
            <p className="ct-section">Quick answers</p>
            <div className="ct-faq-list">
              {inlineFaqs.map((f) => (
                <FaqRow
                  key={f.question}
                  question={f.question}
                  answer={f.answer}
                />
              ))}
            </div>
            <Link to="/faq" className="ct-faq-more">
              Everything else
              <em>→</em>
            </Link>
          </section>
        )}

        {/* ============================================== where */}
        <section className="ct-block ct-where" data-reveal>
          <p className="ct-section">Where I am</p>
          <div className="ct-where-row">
            <div className="ct-where-text">
              <h2>
                Chennai today.
                <br />
                <span className="hl">Hyderabad or Bangalore next.</span>
              </h2>
              <p>
                At CAMS in Chennai, native to Hyderabad, and open to moving for
                the right team — or to staying remote for it.
              </p>
            </div>
            <div className="ct-map">
              <iframe
                title="Hyderabad — preferred base"
                src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d243650.96891459517!2d78.24323405!3d17.412281850000002!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x3bcb99daeaebd2c7%3A0xae93b29a20e27434!2sHyderabad%2C%20Telangana!5e0!3m2!1sen!2sin!4v1716172800000!5m2!1sen!2sin"
                width="100%"
                height="320"
                loading="lazy"
                referrerPolicy="no-referrer-when-downgrade"
              />
              <span className="ct-map-veil" aria-hidden="true" />
            </div>
          </div>
        </section>

      </div>

      {/* The closer. Replaces both the old .ct-end block and the site-wide
          <Footer> on this page: the curtain reveal has to be the last thing
          in the document, and it carries the nav links and the credit line
          the site footer was providing. */}
      <CinematicFooter
        theme={theme}
        onToggle={props.onToggle}
        onStart={scrollToForm}
        onTop={toTop}
      />
    </div>
  );
}

export default Contact;
