/* ============================================================
   The contact page's closer — a "curtain reveal" footer.

   Adapted from a shadcn/Tailwind/TypeScript + GSAP component. This project
   is CRA with plain JS and no Tailwind, so the structure is kept and the
   machinery is swapped for what the page already runs:

     MagneticButton            ->  [data-magnet], the page's own magnetism
     GSAP stagger reveal       ->  [data-reveal] + CSS transition delays
     shadcn --foreground etc.  ->  the page's --fg / --bg / --accent tokens

   That keeps the effect and avoids a 60KB animation runtime for a footer.

   How the reveal works, with no library and nothing driven per frame: the
   footer is genuinely viewport-fixed, and the wrapper above it carries a
   clip-path. (clip-path does NOT create a containing block for fixed
   descendants — only transform / filter / perspective / contain:paint /
   will-change / backdrop-filter do that — so .cf stays pinned to the
   viewport and the wrapper merely clips it.) As the wrapper's box travels
   up the viewport, the window onto the fixed footer grows, and the page
   above appears to slide away and uncover it.

   Everything that moves is either a one-shot [data-reveal] transition or a
   looping CSS animation. An earlier build scrubbed a --p custom property
   from the scroll handler; custom properties cannot be composited, so that
   restyled and repainted the whole clipped layer on every scroll frame.
   ============================================================ */
import React from "react";
import { Link } from "react-router-dom";
import { FaEnvelope, FaFileAlt, FaGithub } from "react-icons/fa";

import Footer from "../../components/footer/Footer";
import { socialMediaLinks } from "../../portfolio.js";
import { resumeDownloadUrl } from "../../utils/downloadResume";

import "./CinematicFooter.css";

/* The marquee's own content. The original shipped a sobriety app's taglines;
   these are the things this page actually claims. */
const MARQUEE = [
  "Open to opportunities",
  "AI / ML engineering",
  "GenAI architecture",
  "Applied research",
  "Tech leadership",
  "Chennai · Hyderabad · Bangalore",
  "Replies in under 24h",
];

function MarqueeRun() {
  return (
    <span className="cf-marquee-run">
      {MARQUEE.map((t, i) => (
        <span className="cf-marquee-item" key={t}>
          {t}
          <i className={i % 2 ? "is-alt" : undefined} aria-hidden="true">
            ✦
          </i>
        </span>
      ))}
    </span>
  );
}

const NAV = [
  { to: "/projects", label: "Projects" },
  { to: "/experience", label: "Experience" },
  { to: "/education", label: "Education" },
  { to: "/learn", label: "Learn" },
  { to: "/blog", label: "Blogs" },
  { to: "/faq", label: "FAQ" },
];

export default function CinematicFooter({ theme, onToggle, onStart, onTop }) {
  return (
    <div className="cf-wrap">
      <footer className="cf">
        {/* ambient light + grid */}
        <span className="cf-aurora" aria-hidden="true" />
        <span className="cf-grid" aria-hidden="true" />

        {/* The giant word behind everything. The outer span owns the
            centring transform; the inner one carries the reveal, so the two
            transforms never overwrite each other. */}
        <span className="cf-giant" aria-hidden="true">
          <b data-reveal>LAXMAN</b>
        </span>

        {/* 1 — the diagonal marquee */}
        <div className="cf-marquee" aria-hidden="true">
          <div className="cf-marquee-track">
            <MarqueeRun />
            <MarqueeRun />
          </div>
        </div>

        {/* 2 — the centre */}
        <div className="cf-main">
          <h2 className="cf-title" data-reveal>
            Then we should
            <br />
            probably talk.
          </h2>

          <div className="cf-actions" data-reveal>
            <div className="cf-actions-row">
              <button
                type="button"
                className="cf-pill is-primary"
                onClick={onStart}
                data-magnet
              >
                <FaEnvelope aria-hidden="true" />
                Start a message
              </button>
              <a
                className="cf-pill is-primary"
                href={`mailto:${socialMediaLinks.gmail}`}
                data-magnet
              >
                Or just email me
              </a>
              <a
                className="cf-pill is-primary"
                href={resumeDownloadUrl()}
                target="_blank"
                rel="noopener noreferrer"
                data-magnet
              >
                <FaFileAlt aria-hidden="true" />
                Résumé
              </a>
            </div>

            <div className="cf-actions-row is-secondary">
              {NAV.map((n) => (
                <Link key={n.to} to={n.to} className="cf-pill" data-magnet>
                  {n.label}
                </Link>
              ))}
              <a
                className="cf-pill"
                href={socialMediaLinks.github}
                target="_blank"
                rel="noopener noreferrer"
                data-magnet
              >
                <FaGithub aria-hidden="true" />
                GitHub
              </a>
            </div>
          </div>
        </div>

        {/* 3 — the bottom bar */}
        <div className="cf-bar">
          <p className="cf-copy">
            © {new Date().getFullYear()} K Laxman · Chennai, IST
          </p>

          {/* The site-wide credit, not a re-typed copy of it — same
              component the experience page and every other page ends with,
              so the beating heart and its click easter egg come along too. */}
          <div className="cf-made">
            <Footer theme={theme} onToggle={onToggle} />
          </div>

          <button
            type="button"
            className="cf-top"
            onClick={onTop}
            aria-label="Back to top"
            data-magnet
          >
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path
                d="M5 10l7-7m0 0l7 7m-7-7v18"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </div>
      </footer>
    </div>
  );
}
